/** Makers known under more than one slug resolve to one entry. */
export const SUIJIN_BRAND_ALIASES: Record<string, string> = { "x-ai": "xai" };

/** Site icons for makers without vector artwork; filled in from the model list at load time. */
export const SUIJIN_BRAND_IMAGES: Record<string, string> = Object.create(null);

export function registerSuijinBrandImages(images: Record<string, string> | undefined): void {
  for (const [maker, url] of Object.entries(images ?? {})) {
    if (url) SUIJIN_BRAND_IMAGES[maker.toLowerCase()] = url;
  }
}

export function suijinHasBrand(brand: string): boolean {
  return brand in SUIJIN_BRAND_PATHS || brand in SUIJIN_BRAND_IMAGES;
}
